package dao;
import conexion.DatabaseConnection;import modelo.Prestamo;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class PrestamoDAO {
 private Prestamo map(ResultSet r)throws SQLException{return new Prestamo(r.getInt("id"),r.getInt("id_estudiante"),r.getInt("id_libro"),r.getString("estudiante"),r.getString("libro"),r.getDate("fecha_prestamo").toLocalDate(),r.getDate("fecha_devolucion").toLocalDate(),r.getBoolean("devuelto"));}
 private static final String BASE="SELECT p.id,p.id_estudiante,p.id_libro,e.nombre estudiante,l.titulo libro,p.fecha_prestamo,p.fecha_devolucion,p.devuelto FROM prestamos p JOIN estudiantes e ON e.id=p.id_estudiante JOIN libros l ON l.id=p.id_libro ";
 public List<Prestamo> listar()throws SQLException{List<Prestamo>a=new ArrayList<>();try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(BASE+"ORDER BY p.devuelto,p.fecha_devolucion DESC");ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}return a;}
 public synchronized void devolver(int id)throws SQLException{try(Connection c=DatabaseConnection.getInstance().getConnection()){c.setAutoCommit(false);try{int libro;try(PreparedStatement p=c.prepareStatement("SELECT id_libro FROM prestamos WHERE id=? AND devuelto=FALSE FOR UPDATE")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Préstamo inexistente o ya devuelto.");libro=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("UPDATE prestamos SET devuelto=TRUE WHERE id=? AND devuelto=FALSE")){p.setInt(1,id);if(p.executeUpdate()!=1)throw new SQLException("No se pudo actualizar el préstamo.");}try(PreparedStatement p=c.prepareStatement("UPDATE libros SET stock=stock+1 WHERE id=?")){p.setInt(1,libro);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}}}
 public List<Object[]> masPrestados()throws SQLException{List<Object[]>a=new ArrayList<>();String s="SELECT l.titulo,COUNT(*) total FROM prestamos p JOIN libros l ON l.id=p.id_libro GROUP BY l.id,l.titulo ORDER BY total DESC,l.titulo";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(s);ResultSet r=p.executeQuery()){while(r.next())a.add(new Object[]{r.getString(1),r.getInt(2)});}return a;}
 public List<Object[]> historial()throws SQLException{List<Object[]>a=new ArrayList<>();String s="SELECT e.nombre,l.titulo,p.fecha_prestamo,p.fecha_devolucion,p.devuelto FROM prestamos p JOIN estudiantes e ON e.id=p.id_estudiante JOIN libros l ON l.id=p.id_libro ORDER BY e.nombre,p.fecha_prestamo DESC";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(s);ResultSet r=p.executeQuery()){while(r.next())a.add(new Object[]{r.getString(1),r.getString(2),r.getDate(3),r.getDate(4),r.getBoolean(5)?"Sí":"No"});}return a;}
 public List<Object[]> pendientes()throws SQLException{List<Object[]>a=new ArrayList<>();String s="SELECT e.nombre,l.titulo,p.fecha_prestamo,p.fecha_devolucion,CASE WHEN p.fecha_devolucion<CURRENT_DATE THEN 'Atrasado' ELSE 'Vigente' END estado FROM prestamos p JOIN estudiantes e ON e.id=p.id_estudiante JOIN libros l ON l.id=p.id_libro WHERE p.devuelto=FALSE ORDER BY p.fecha_devolucion";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(s);ResultSet r=p.executeQuery()){while(r.next())a.add(new Object[]{r.getString(1),r.getString(2),r.getDate(3),r.getDate(4),r.getString(5)});}return a;}
}